export const GUIDES_AR_4: Record<string, { title?: string; intro?: string; sections?: { h: string; ps: string[] }[]; steps?: string[]; faq?: { q: string; a: string }[]; aliasesAr?: string[] }> = {
  'sihr-black-magic-jinn-response': { title: 'السحر والجن في الاسلام الفهم والرد الشرعي', intro: 'السحر حقيقة في الاسلام لكنه لا يضر الا باذن الله. تعلم الفرق بين السحر والمرض وقاعدة الطبيب اولا وبرنامج الرقية اليومي لكسره بالصبر.', sections: [ { h: 'التمييز اولا سحر او جن او مرض طبي', ps: ['السحر ثابت في القران حيث تعلم الناس السحر في بابل في الاية 2:102 وانهم لا يضرون به احدا الا باذن الله. واكثر الحالات المشتبهة هي امراض طبية او نفسية او خلافات زوجية او ابتلاءات عادية. والقاعدة مراجعة طبيب ثقة اولا وعلاج ما يفسره الطب مع الرقية معا وعدم ترك الدواء لتشخيص روحي من راق غير موثوق.', 'احذر التشخيصات الكاذبة التي تدعي اليقين بالسحر من صورة او اسم او منام وحده او ادعاء الكشف. واحذر من يطلب مالا كبيرا مقدما او يامر بدفن اشياء او عقد خيوط او ذبائح او زيارة مقابر ليلا. الصادق يقول قد يكون كذا وعالج الطريقين معا ولا ياخذ الا قليلا او لا شيء.'] }, { h: 'برنامج الرقية وما لا اصل له', ps: ['برنامج العلاج هو المحافظة على الصلوات الخمس في وقتها والرقية الذاتية اليومية بالفاتحة واية الكرسي واخر ايتي البقرة والمعوذات ثلاثا واذكار الصباح والمساء دون انقطاع وقراءة سورة البقرة في البيت فان اخذها بركة وتركها حسرة واكل سبع تمرات عجوة بعض الصباحات والاغتسال بماء السدر المقروء عليه. ويستمر ذلك شهورا مع الصبر والتوبة.', 'ومما لا اصل له دفع مال لضمان فك السحر وتمائم فيها مربعات وارقام واسماء غير مفهومة وطقوس ارجاع الجن والسحر المضاد لفك السحر فهو محرم وسؤال العرافين ومن ترك العبادة بحجة ان السحر يمنعه. شفاء الله اطول بقاء من كل عقد.'] } ], steps: ['راجع الطبيب اولا وعالج الاسباب الطبية والنفسية مع الرقية.', 'حافظ على الصلوات الخمس وابدأ الرقية الذاتية واذكار الصباح والمساء.', 'اقرأ سورة البقرة في البيت وكل سبع تمرات عجوة بعض الصباحات.', 'اغتسل بماء السدر المقروء عليه واستمر شهورا مع التوبة.', 'ارفض العلاجات المدفوعة المضمونة والتمائم والسحر المضاد تماما.'], faq: [ { q: 'ماذا افعل اذا اصبت بالسحر', a: 'راجع الطبيب اولا وحافظ على الصلوات الخمس واعمل الرقية الذاتية بالفاتحة واية الكرسي والمعوذات واقرأ البقرة في البيت واستمر شهورا ولا تدفع مالا لعلاج مضمون.' }, { q: 'كيف اعرف هل هو سحر ام مرض طبي', a: 'غالبا لا يمكن الجزم لذلك القاعدة هي الجمع بين الطريقين دواء للجسد ورقية للغيب. ومن يدعي اليقين من صورة او اسم فهو علامة دجل.' }, { q: 'هل سورة البقرة تكسر السحر', a: 'قراءتها تطرد الشياطين وتركها حسرة واخر ايتيها تكفيان في الليل. اقرأها في البيت ضمن البرنامج الكامل لا وحدها.' } ], aliasesAr: ['علاج السحر بالرقية الشرعية', 'السحر والجن والعلاج في الاسلام'] },
  'fake-raqi-amulet-red-flags': { title: 'الرقاة الكاذبون ودجل التمائم سبع علامات تحذير', intro: 'دجل بعض الرقاة يستنزف المال ويفسد الايمان. تعلم العلامات السبع المال المقدم والخلوة والتمائم غير المفهومة وضمان الشفاء وكيف تجد راقيا موثوقا.', sections: [ { h: 'العلامات الحمراء السبع', ps: ['الاولى طلب مال كبير مقدما او رسوم تزيد مع التخويف فالرقية الصحيحة غالبا مجانية او بكلفة رمزية. والثانية الخلوة بالنساء او لمس غير المحارم بحجة العلاج وهو محرم. والثالثة التمائم ذات الكتابة غير المفهومة والمربعات والارقام والاسماء المجهولة فما لا يفهم لا يجوز تعليقه مهما قال البائع.', 'والرابعة ضمان الشفاء بنسبة مئة بالمئة فالشفاء بيد الله وحده والضمان كذب. والخامسة طلب اسم الام او صورة او ملابس او شعر للتشخيص وهي ادوات العرافين لا الرقية. والسادسة امر باعمال محرمة كالذبح لغير الله وطقوس المقابر ودفن الاشياء. والسابعة ادعاء علم الغيب ورؤية الجن فهي تلاعب فابتعد عنها جميعا.'] }, { h: 'الراقي الموثوق وقاعدة الرقية الذاتية', ps: ['الراقي الموثوق يقرأ القران والادعية الصحيحة بصوت مسموع ولا ياخذ الا قليلا او لا شيء ولا يلمس ولا يختلي ولا يكتب الا قرانا ودعاء مفهوما وينصح بالصلاة والرقية الذاتية ويحيل الحالات الطبية الى الاطباء. واحكم عليه بهذه الصفات لا بالشهرة وعدد المتابعين.', 'والافضل الرقية الذاتية وهي الاصل فالفاتحة واية الكرسي والمعوذات على نفسك مجانية ولا خطر فيها. علم كل افراد الاسرة هذا البرنامج اليومي وابلغ عن المحتالين لدى العلماء والجهات المختصة لحماية الاسر الاخرى.'] } ], steps: ['احفظ العلامات السبع قبل زيارة اي راق.', 'قدم الرقية الذاتية فهي مجانية وامنة وهي السنة.', 'اذا طلبت المساعدة فتاكد من قراءة مسموعة وعدم اللمس والخلوة وعدم المال الكبير.', 'ارفض التمائم غير المفهومة وتشخيص اسم الام وضمان الشفاء.', 'ابلغ عن المحتالين لدى العلماء والجهات لحماية الاخرين.'], faq: [ { q: 'كيف اعرف ان الراقي صادق', a: 'يقرأ القران والادعية الصحيحة بصوت مسموع ولا يلمس ولا يختلي واجره قليل او لا شيء وكتابته مفهومة وينصح بالصلاة والرقية الذاتية ويحيل المرض الى الاطباء.' }, { q: 'هل لبس التميمة جائز في الاسلام', a: 'التميمة غير المفهومة ذات المربعات والارقام مرفوضة عند العلماء. وحتى تميمة القران تركها كثير من العلماء. والرقية المقروءة بنفسك هي السنة الامنة.' }, { q: 'لماذا يطلب اسم امي', a: 'هذه طريقة العرافين في التعريف لا الرقية. اتركه فورا فان سؤاله يبطل ثواب الصلاة اربعين ليلة.' } ], aliasesAr: ['علامات الراقي الكاذب', 'حكم التمائم وتعليقها'] },
  'qada-missed-prayers-how-to': { title: 'قضاء الصلوات الفائتة كيف تقضي ما فاتك', intro: 'كيف تقضي سنوات من الصلوات الفائتة تب الى الله وابدأ اليوم واضف قضاء واحدا مع كل فرض وقدر العدد تقديرا معقولا.', sections: [ { h: 'الحكم ونقطة البداية', ps: ['ترك الصلاة بلا عذر ذنب كبير وجمهور العلماء من الحنفية والمالكية والشافعية والحنابلة يرون ان الصلوات الفائتة دين يجب قضاؤه مع تقدير العدد عند الجهل به. وبعض العلماء المعاصرين يرون ان التوبة الصادقة مع الاكثار من النوافل تكفي لما ترك طويلا. اعرف القولين ثم اتبع العلماء الموثوقين.', 'ونقطة البداية في كل الاحوال واحدة وهي التوبة الصادقة وعدم ترك اي صلاة من اليوم والبدء بالقضاء فورا. وحيلة الشيطان هنا الياس من كثرة العدد بينما قضاء واحد ثابت يوميا ينهي دين سنوات خلال سنوات. ابدأ قليلا واستمر.'] }, { h: 'جدول واحد مع كل فرض والتقدير', ps: ['الطريقة المستمرة هي صلاة قضاء واحد مع كل صلاة يومية قضاء فجر مع الفجر وقضاء ظهر مع الظهر وهكذا فتصلي خمسة قضاء يوميا دون مشقة كبيرة. وسجل في دفتر بخمسة اعمدة وكل قضاء يصلى مثل اصله الفجر اثنتان والظهر اربع والعصر اربع والمغرب ثلاث والعشاء اربع مع الوتر. وبخمسة يوميا تقضي سنة في نحو سنة.', 'وللعدد المجهول قدر تقديرا معقولا سنوات الترك في 365 في 5 يعطي الدين التقريبي واعمل عليه دون وسوسة بالرقم الدقيق. ولا توجد صيغة ثابتة لقضاء العمري بعدد معين يغفر العمر كله. والطريق الصحيح تقدير صادق مع انجاز ثابت واستعن باداة اوقات الصلاة وحافظ على الجمعة.'] } ], steps: ['تب توبة صادقة واعزم على عدم ترك اي صلاة من اليوم.', 'قدر الدين سنوات الترك في 365 في 5 صلوات يوميا تقريبا.', 'صل قضاء واحدا مع كل فرض خمسة يوميا بنفس ركعات الاصل.', 'سجل كل قضاء في دفتر حتى تنهي العدد المقدر.', 'اكثر من النوافل والاستغفار واستشر العلماء في حالتك.'], faq: [ { q: 'كيف اقضي صلوات سنوات كثيرة', a: 'قدر المجموع سنوات في 365 في 5 ثم صل قضاء واحدا مع كل فرض خمسة يوميا وسجله حتى ينتهي التقدير وابدأ اليوم دون تاخير.' }, { q: 'هل يجب قضاء الفوائت ام تكفي التوبة', a: 'الجمهور يوجب القضاء وبعض المعاصرين يقبل التوبة مع كثير النوافل لما ترك طويلا. اتبع العلماء الموثوقين وفي كل الاحوال لا تترك صلاة بعد اليوم.' }, { q: 'هل توجد صيغة ثابتة لقضاء العمري', a: 'لا توجد صيغة ثابتة في المصادر. قدر ما فاتك تقديرا معقولا واعمل عليه بثبات فهذا هو الطريق الصحيح.' } ], aliasesAr: ['كيفية قضاء الصلوات الفائتة', 'قضاء الصلاة وحكمه'] },
  'haiz-nifas-purity-guide': { title: 'احكام الحيض والنفاس والطهارة في الاسلام', intro: 'احكام الحيض والنفاس مدتها وما يتوقف اثناءها وعلامات الطهر وقضاء الصوم والاستحاضة دليل الطهارة الكامل للمرأة.', sections: [ { h: 'المدد وعلامات الطهر وما يتوقف', ps: ['الحيض اقله نحو ثلاثة ايام واكثره عشرة ايام عند الحنفية وخمسة عشر يوما عند الجمهور فالدم في العادة ضمن الاكثر حيض وما جاوزه استحاضة باحكام مختلفة. والنفاس اكثره اربعون يوما ومتى انقطع الدم وظهرت القصة البيضاء او الجفاف الكامل فقد حصل الطهر فتغتسل وتعود للعبادة.', 'واثناء الحيض والنفاس تتوقف اربعة الصلوات الخمس ولا قضاء عليها والصوم ويقضى بعد رمضان ومس المصحف مباشرة والبقاء في المسجد والطواف حتى الطهر. ويستمر الذكر والدعاء وسماع القران وكل الادعية اليومية فالحيض لا يقطع المرأة عن الله.'] }, { h: 'القضاء والاستحاضة واثر الحبوب', ps: ['الصلوات الفائتة اثناء الحيض لا تقضى ابدا لقول عائشة كنا نؤمر بقضاء الصوم ولا نؤمر بقضاء الصلاة. وصوم رمضان الفائت يقضى يوما بيوم قبل رمضان التالي ما امكن. وحبوب منع الحمل او العلاج التي تغير العادة تحير النمط والقاعدة الدم في ايام العادة ضمن الاكثر حيض وما استمر بعده استحاضة واسالي عالما موثوقا عن حالتك الدقيقة.', 'والاستحاضة وهي الدم الزائد عن الاكثر او خارج النمط لا تمنع العبادة فتوضئي لكل وقت صلاة واستعملي الحفاظ وصلي وصومي وادخلي المسجد عاديا. قال النبي لفاطمة بنت ابي حبيش انه عرق وليس حيضا فتوضئي لكل صلاة.'] } ], steps: ['سجلي ايام الدورة فالدم في النمط ضمن الاكثر حيض.', 'اوقفي الصلاة والصوم ومس المصحف والطواف وواصلي الذكر والدعاء.', 'عند علامة الطهر القصة البيضاء او الجفاف اغتسلي وعودي للعبادة.', 'الدم الزائد عن الاكثر استحاضة توضئي لكل صلاة واعبدي عاديا.', 'اقضي صوم رمضان الفائت يوما بيوم ولا قضاء للصلاة.'], faq: [ { q: 'هل اصلي اثناء الحيض في الاسلام', a: 'لا تتوقف الصلوات الخمس اثناء الحيض والنفاس ولا قضاء لها. عودي بالغسل عند علامات الطهر.' }, { q: 'كم اكثر مدة الحيض', a: 'عشرة ايام عند الحنفية وخمسة عشر عند الجمهور. وما زاد عن الاكثر استحاضة بوضوء جديد لكل صلاة مع استمرار العبادة.' }, { q: 'هل اصوم اثناء الحيض وهل اقضي', a: 'لا تصومي اثناء الدم واقضي كل يوم من رمضان بعده يوما بيوم. اما الصلاة فلا تقضى بخلاف الصوم.' } ], aliasesAr: ['احكام الحيض والنفاس والصلاة', 'الاستحاضة والطهارة للمرأة'] },
  'talaq-khula-iddah-rules': { title: 'الطلاق والخلع والعدة في الاسلام احكامها', intro: 'اجراءات الطلاق في الاسلام والخلع للمرأة ومدد العدة الطلاق السني وطلاق الثلاث ومدد الانتظار وحقوق النفقة.', sections: [ { h: 'الطلاق السني وطلاق الثلاث والخلع', ps: ['الطلاق السني لفظ واحد في طهر لم يجامع فيه ثم انتظار العدة دون اخراج الزوجة والمراجعة مفتوحة في الطلقتين الاوليين مع شهود وتوثيق هادئ يحفظ الحقوق. والفاظ الغضب والسكر والاكراه والطلاق المعلق كلها تحتاج حكما فرديا من عالم ولا تحكم بنفسك على النتيجة.', 'والثلاث في مجلس واحد بدعة محرمة بالاتفاق في الطريقة ويعدها الجمهور ثلاثا تنهي الزواج بينما يعدها ابن تيمية وابن القيم واحدة رجعية. ولان الاسر تعيش النتيجة استشر عالما ومحاميا فورا ولا تعمل بفتاوى الانترنت. وللمرأة المتضررة طلب الخلع بعوض غالبا برد المهر عبر العلماء او المحاكم كما فعلت زوجة ثابت بن قيس.'] }, { h: 'مدد العدة والنفقة والحضانة', ps: ['العدة وهي مدة الانتظار قبل الزواج الجديد ثلاثة قروء للمطلقة الحائض وحتى الوضع للحامل مطلقة او ارملة واربعة اشهر وعشرة ايام للارملة وثلاثة اشهر قمرية لليائسة او الصغيرة ولا عدة قبل الدخول والخلوة. وحكمتها ثبوت الحمل وفسحة للصلح.', 'واثناء عدة الرجعية تبقى الزوجة في بيت الزوج مع النفقة الكاملة وبعد البائن او عدة الوفاة يستمر السكن مع اختلاف النفقة حسب المذهب فسجل كل اتفاق كتابة. وحضانة الصغار للام في السن المبكرة مع نفقة ثابتة على الاب وتحتاج الحضانة والنفقة والتسجيل القانوني الى عالم ومحام في بلدك معا.'] } ], steps: ['قدم الصلح والتحكيم اولا فالطلاق ابغض المباح.', 'عند التعذر لفظ واحد في طهر مع شهود وتوثيق هادئ.', 'التزم العدة ثلاث دورات وحتى الوضع للحامل واربعة اشهر وعشرة للارملة.', 'رتب النفقة والحضانة كتابة واستشر عالما ومحاميا.', 'المتضررة تطلب الخلع عبر العلماء او المحاكم.'], faq: [ { q: 'ما اجراء الطلاق الصحيح في الاسلام', a: 'لفظ واحد في طهر دون جماع مع شهود ثم انتظار العدة مع بقاء الزوجة في السكن والمراجعة مفتوحة في الطلقتين الاوليين.' }, { q: 'هل الثلاث في مجلس واحد تقع ثلاثا', a: 'الجمهور يوقعها ثلاثا نهائية واقلية تعدها واحدة. وهي اثمة في الطريقة بكل الاراء فاستشر عالما فورا في حالتك.' }, { q: 'كم مدة العدة بعد الطلاق او الوفاة', a: 'ثلاث دورات بعد الطلاق وحتى الوضع للحامل واربعة اشهر وعشرة للارملة وثلاثة اشهر بعد الياس ولا شيء قبل الدخول.' } ], aliasesAr: ['احكام الطلاق والعدة', 'الخلع واجراءاته في الاسلام'] },
  'new-muslim-starter-guide': { title: 'دليل المسلم الجديد من الشهادة الى اول صلاة', intro: 'كيف تصبح مسلما انطق الشهادة واغتسل وتعلم الوضوء وصلاتك الاولى ثم اتبع طريق البداية اسبوعا باسبوع.', sections: [ { h: 'الشهادة والتطهير الاول', ps: ['دخول الاسلام بخطوة واحدة ان تقول بصدق اشهد ان لا اله الا الله واشهد ان محمدا رسول الله مع الايمان والعزم بشهود ان تيسر او وحدك فالله يقبل فورا وتمحى الذنوب الماضية. ثم اغتسل الغسل الكامل ولا حاجز بينك وبين الاسلام لا مراسم ولا رسوم ولا انتظار.', 'ثم تعلم الوضوء وصلاة واحدة في كل مرة وابدأ بالفجر مستعينا بدليل الصلاة خطوة بخطوة. وصل ما تقدر من اليوم الاول حتى اثناء التعلم وقراءة الفاتحة ببطء من حفظك او ورقة صحيحة وكل صلاة مبكرة متعثرة جهد محبوب لا عبادة فاشلة.'] }, { h: 'طريق الاسابيع والاسرة والاسم والخرافات', ps: ['الاسبوع الاول الشهادة والغسل والوضوء والفجر واوقات الصلوات. والاسابيع التالية اضف بقية الصلوات واحفظ الفاتحة واذكار الصباح والمساء. والشهر الثاني اساسيات الصوم قبل رمضان والزكاة وقواعد الطعام الحلال وابحث عن مسجد ومعلم محلي. والشهر الثالث قراءة القران والسيرة وصحبة المجتمع المسلم.', 'اخبر اسرتك بلطف وتدريج وبر الوالدين غير المسلمين واجب ولا تغير اسمك الا اذا حمل معنى محرما والختان للبالغين حسب نصيحة الطبيب والعالم. وتجاهل الخرافات فلا يشترط الكمال اولا والوشم القديم لا يمنع الاسلام. واستعمل ادوات اوقات الصلاة والقبلة يوميا وراسل اماما محليا مبكرا.'] } ], steps: ['انطق الشهادة بصدق وحدك او بشهود فانت مسلم فورا.', 'اغتسل وتعلم الوضوء في نفس اليوم.', 'تعلم الفجر اولا بدليل الصلاة واضف الصلوات اسبوعا باسبوع.', 'احفظ الفاتحة وابدأ اذكار الصباح والمساء.', 'جد مسجدا ومعلما في الاسبوع الاول واخبر اسرتك بلطف.', 'في الشهرين التاليين الصوم والطعام الحلال وقراءة القران والسيرة.'], faq: [ { q: 'كيف اصبح مسلما', a: 'انطق الشهادة بصدق وايمان اشهد ان لا اله الا الله واشهد ان محمدا رسول الله ثم اغتسل. ولا تشترط مراسم ولا رسوم ولا شهود للصحة وان كان الشهود يعين في التوثيق.' }, { q: 'هل اغير اسمي بعد الاسلام', a: 'فقط اذا حمل معنى محرما كعبادة غير الله. والاسماء العادية تبقى وكثير من الصحابة احتفظوا باسمائهم. واختيار اسم مسلم اختياري لا عاجل.' }, { q: 'ماذا يتعلم المسلم الجديد اولا', a: 'الوضوء ثم الصلوات الخمس واحدة واحدة ثم الفاتحة ثم اساسيات الصوم والطعام الحلال بنفس ترتيب الدليل. والزم مسجدا ومعلما من الاسبوع الاول.' } ], aliasesAr: ['كيف ادخل الاسلام', 'دليل المسلم الجديد والشهادة'] },
  'muslim-death-checklist-wasiyyah': { title: 'دليل الوفاة في الاسلام الجنازة والوصية', intro: 'قائمة الجنازة والوصية الاسلامية خطوات الساعات الاولى وترتيب الغسل والجنازة واقسام الوصية وصلتها بالميراث.', sections: [ { h: 'الساعات الاولى وترتيب الجنازة', ps: ['عند الوفاة اغمض العينين وقل بسم الله وعلى ملة رسول الله وغط الجسد وسجل الديون العاجلة كتابة فالنفس معلقة بالدين وابلغ الاسرة والمسجد ورتب الشعائر بسرعة فالدفن في نفس اليوم سنة. والترتيب الغسل وترا بماء وسدر وكافور والكفن ثلاثة اثواب للرجل وخمسة للمرأة وصلاة الجنازة باربع تكبيرات ثم الدفن باتجاه القبلة.', 'واحزن بدموع هادئة وهي جائزة دون نواح وضرب خدود وتمزيق ثياب فهي محرمة. وعز بقول انا لله وانا اليه راجعون وزر القبر واجعل الحزن صدقة جارية فالميت ينتفع بالصدقة والعلم النافع ودعاء الولد الصالح لا بالقراء المستاجرين وولائم الايام المحددة.'] }, { h: 'الوصية وقالبها والميراث', ps: ['كل بالغ يجب ان يكتب وصيته الان فلا يحل ان يبيت ليلتين دون كتابتها. واقسامها بالترتيب سجل الديون اولا فتقضى قبل كل شيء وامنيات الجنازة بدفن سريع بسيط دون اسراف ووصايا حتى الثلث لغير الورثة وللصدقة ولا وصية لوارث قراني دون رضا الورثة واوصياء للصغار وكلمات المرور والاصول والحقوق لك. ووقع وارخ واشهد واحفظها حيث تجدها الاسرة.', 'وبعد الديون والوصايا يقسم الباقي بالميراث وهي حصص ثابتة من الله في الايات 4:11 و12 و176 لا بالتفاوض فاستعمل حاسبة الميراث للتقسيم الدقيق. واعلم ان الوصية تعمل داخل قانون بلدك فراجع محاميا لموافقتها مع النظام حتى ينفذها الورثة دون نزاع.'] } ], steps: ['عند الوفاة اغمض العينين وغط الجسد وسجل الديون وابلغ الاسرة والمسجد.', 'رتب الغسل والكفن وصلاة الجنازة والدفن السريع باتجاه القبلة.', 'احزن بهدوء واجعل صدقة جارية علما ودعاء وصدقة.', 'اكتب وصيتك الان الديون وامنيات الجنازة ووصايا حتى الثلث والاوصياء.', 'اقسم الباقي بحصص الميراث ووافق الوصية مع القانون المحلي.'], faq: [ { q: 'ماذا نفعل اولا عند وفاة مسلم', a: 'اغمض العينين وغط الجسد وسجل الديون وابلغ الاسرة والمسجد ثم رتب الغسل والكفن وصلاة الجنازة والدفن بسرعة فالدفن في نفس اليوم سنة.' }, { q: 'ماذا تشمل الوصية الاسلامية', a: 'الديون اولا وامنيات الجنازة ووصايا حتى الثلث لغير الورثة واوصياء للصغار وسجل الاصول موقعة ومشهودة ومحفوظة وموافقة للقانون.' }, { q: 'من يرث ماذا في الميراث الاسلامي', a: 'حصص قرانية ثابتة للزوج والوالدين والاولاد وغيرهم بعد الديون والوصايا واستعمل حاسبة الميراث لتقسيم حالتك بدقة.' } ], aliasesAr: ['احكام الجنازة والدفن', 'الوصية والميراث في الاسلام'] },
  'riba-interest-modern-money': { title: 'الربا في الاسلام الرهن العقاري والبنوك والمال الحديث', intro: 'الربا في الاسلام للحياة الحديثة لماذا الفائدة حرام ونماذج التمويل الحلال مقارنة والوظائف البنكية والبطاقات والقروض وكيف تتخلص من الفائدة.', sections: [ { h: 'لماذا الربا ونماذج التمويل', ps: ['الربا كل زيادة مشروطة على قرض وهو محرم بنصوص قاطعة في الايات 2:275 الى 279 واحل الله البيع وحرم الربا مع اعلان الحرب على الاستمرار فيه. ويشمل التحريم الاخذ والدفع والشهادة والكتابة لذلك يدخل الرهن العقاري التقليدي فيه عند جمهور العلماء مهما كان الاحتياج.', 'وتوجد ثلاثة نماذج بصيغ حلال حيث تتوفر المرابحة بشراء البنك ثم بيع بمرابحة معلومة والاجارة المنتهية بالتمليك مع المشاركة المتناقصة وصناديق التمويل الحلال المعتمدة من علماء فقارن التوثيق والتكلفة الكلية ومصرف رسوم التاخير واسماء العلماء لا العلامة فقط. وحيث لا يوجد نموذج حلال ينصح العلماء بالايجار والادخار وبيوت اصغر حتى تستفتي جهة فقهية فالضرورة فتوى فردية لا تعلن بنفسك.'] }, { h: 'الوظائف والبطاقات والقروض والتخلص من الفائدة', ps: ['العمل المباشر في الفائدة ككتابة عقود القروض وبيع الرهن التقليدي لا يجوز لحديث لعن الشاهد والكاتب اما الوظائف الخلفية او التقنية في مؤسسات مختلطة فتحتاج فتوى تصف عملك بدقة. وبطاقة الائتمان اداة لا حكم فسدادها كاملا قبل الفائدة يتجنب الربا لكنه يقارب الدين فيجوز بحذر مع تحذير العلماء من الوقوع. وقروض الدراسة بالفائدة تحت نفس التحريم فقلل الاقتراض وابحث عن منح واجعل الضرورة سؤال فتوى.', 'والفائدة المقبوضة او العالقة يجب التخلص منها باعطائها للمنفعة العامة او الفقراء دون نية ثواب فهي تطهير لا صدقة واغلق الحسابات الربوية ما امكن. وللادخار والاستثمار استعمل حسابات المضاربة وافحص الاسهم من الدخل الحرام ثم طهر مالك سنويا بزكاة الاستثمار.'] } ], steps: ['افهم القاعدة الزيادة المضمونة على القرض ربا اخذا ودفعا.', 'للسكن قارن المرابحة والاجارة والصناديق المعتمدة والا فاستاجر وادخر.', 'راجع البطاقات والقروض اسدد قبل الفائدة وقلل الاقتراض واسال العلماء.', 'تخلص من الفائدة المقبوضة للمنفعة العامة دون نية ثواب.', 'لوظائف البنوك ودعاوى الضرورة خذ فتوى فردية ولا تعلن بنفسك.'], faq: [ { q: 'هل الرهن العقاري حرام في الاسلام', a: 'الرهن التقليدي بالفائدة يدخل في الربا عند جمهور العلماء. استعمل المرابحة او الاجارة او الصناديق المعتمدة حيث تتوفر والا فاستشر العلماء فالضرورة فتوى فردية.' }, { q: 'هل العمل في البنك جائز', a: 'الوظائف المباشرة في الفائدة كعقود القروض وبيع الرهن التقليدي لا تجوز والوظائف الاخرى تحتاج فتوى تصف عملك بدقة لعالم.' }, { q: 'ماذا افعل بالفائدة المقبوضة', a: 'اعطها للمنفعة العامة او الفقراء دون نية ثواب فهي تطهير لا صدقة وانقل اموالك الى هياكل حلال.' } ], aliasesAr: ['حكم الربا والفوائد البنكية', 'التمويل العقاري الحلال'] },
  'after-salah-adhkar-routine': { title: 'التسبيح بعد الصلاة برنامج الاذكار اليومي', intro: 'التسبيح بعد الصلاة بالترتيب سبحان الله 33 والحمد لله 33 والله اكبر 34 واية الكرسي والمعوذات برنامج الاذكار الكامل.', sections: [ { h: 'البرنامج الاساسي بالترتيب', ps: ['ابق جالسا بعد السلام وقل استغفر الله ثلاثا ثم اللهم انت السلام ومنك السلام ثم العد المشهور سبحان الله 33 والحمد لله 33 والله اكبر 34 فمن فعلها غفرت ذنوبه ولو مثل زبد البحر ثم اختم بلا اله الا الله وحده لا شريك له مرة. واضف اية الكرسي فلا يمنع قارئها من الجنة الا الموت والمعوذات مرة بعد كل صلاة وثلاثا بعد الفجر والمغرب.', 'والبرنامج يستغرق اقل من خمس دقائق ويفوق الاسراع الى الهاتف فالملائكة تدعو لمن بقي في مصلاه على وضوء. والمرأة في بيتها لها نفس اجر اذكار الجلوس فالمكان لا يهم وحضور القلب كل شيء. واستعمل اداة التسبيح لاهداف 33 و100 ان نسيت العد بالاصابع.'] }, { h: 'زيادات الفجر والمغرب والاخطاء الشائعة', ps: ['بعد الفجر والمغرب اضف لا اله الا الله وحده عشر مرات باجر عتق واللهم اجرني من النار سبعا وبسم الله الذي لا يضر ثلاثا وكلها في صفحات الادعية مع العربية والصوت. واذكار الصباح تلحق بعد الفجر واذكار المساء بعد العصر او المغرب وربطها باوقات الصلاة سر الثبات مع الانشغال.', 'ومن الاخطاء الاسراع بالعد دون وعي اللسان والكلام اثناء الذكر فاكمل بهدوء دون اعادة وترك اية الكرسي وهي اعلى اية بعد الصلاة واعتبار البرنامج مهملا دائما وهو سنة لم يتركها النبي. خمس دقائق خمس صلوات باجور عظيمة.'] } ], steps: ['بعد السلام استغفر الله 3 ثم اللهم انت السلام.', 'عد سبحان الله 33 والحمد لله 33 والله اكبر 34.', 'اختم بالتهليل مرة واقرأ اية الكرسي.', 'اقرأ المعوذات مرة وثلاثا بعد الفجر والمغرب.', 'بعد الفجر والمغرب اضف التهليل 10 واجرني من النار 7 واذكار الصباح والمساء.'], faq: [ { q: 'ما التسبيح بعد الصلاة', a: 'سبحان الله 33 والحمد لله 33 والله اكبر 34 ثم التهليل مرة واية الكرسي والمعوذات في اقل من خمس دقائق وتغفر الذنوب.' }, { q: 'ما ادعية بعد الفجر والمغرب خاصة', a: 'اضف التهليل عشرا واللهم اجرني من النار سبعا والمعوذات ثلاثا ومجموعتي الصباح والمساء وكلها في صفحات الادعية.' }, { q: 'هل استعمل السبحة او الهاتف بعد الصلاة', a: 'نعم الاصابع افضل لانها تشهد والعداد واداة التسبيح معينات جائزة. وحضور القلب اهم من الوسيلة.' } ], aliasesAr: ['اذكار بعد الصلاة', 'التسبيح بعد الصلاة 33'] },
  'dreams-in-islam-guide': { title: 'الاحلام في الاسلام انواعها ومعناها وما تفعل', intro: 'الاحلام في الاسلام الرؤيا الصادقة جزء من 46 جزءا من النبوة. تعلم الانواع الثلاثة وما تفعل بعد الحلم الجيد والسيئ وحدود التفسير.', sections: [ { h: 'الانواع الثلاثة وحدود التفسير الصارمة', ps: ['قسم النبي الاحلام ثلاثة بشرى من الله وهي الرؤيا الصالحة جزء من ستة واربعين من النبوة وحلم مزعج من الشيطان ليحزنك وحديث نفس من هموم النهار. والرؤيا الصادقة تقترب من الصادقين واخر الليل قبل الفجر واكثر احلام اليوم الواضحة من النوع الثالث وهي اعادة الدماغ لاحداث اليوم لا رسائل تحتاج مفسرا.', 'وتفسير الاحلام حق وسورة يوسف دليله لكن حدوده صارمة فلا قاموس ثابت الثعبان يعني كذا دائما والرموز تختلف بالشخص والثقافة والسياق ولا يفسر الا عالم سرا مع قول خيرا ان شاء الله. وتجاهل مفسرين التواصل الذين يطلبون مالا او بيانات ولا تبن زواجا او طلاقا او مالا على حلم وحده فالاستخارة والمشورة هي الفيصل.'] }, { h: 'ما تفعل بعد الحلم الجيد والكابوس', ps: ['بعد الحلم الجيد احمد الله ولا تخبر الا من يحبك فسورة يوسف 12:5 تحذر من حسد المعلنة واسال الله خيرها ولا تفاخر. وبعد الكابوس انفث عن يسارك ثلاثا وتعوذ قل اعوذ بالله من الشيطان الرجيم مع دعاء الحلم السيئ وتحول الى جنبك الاخر وصل ركعتين ان استيقظت ولا تخبر احدا فانها لن تضره. وبروتوكول الكابوس يعمل من اول ليلة.', 'والاحلام المخيفة المتكررة مع الجاثوم او الفزع تستحق الطريقين الحماية الليلية بالوضوء واية الكرسي واخر ايتي البقرة والمعوذات ثلاثا مع المسح ومراجعة طبيب لاضطراب النوم او الاثار النفسية او الادوية. فالشيطان يستغل المجهد وحصن اذكار قبل النوم كقفل الباب وعلم الاطفال المعوذات الثلاث.'] } ], steps: ['صنف الحلم بشرى او ازعاج شيطاني او حديث نفس نهاري.', 'الحلم الجيد احمد الله واخبر الاحبة فقط واسال الله خيره.', 'الكابوس انفث يسارا 3 وتعوذ وتحول وصل ان استيقظت ولا تخبر احدا.', 'حصن نومك ليلا بالوضوء واية الكرسي واخر البقرة والمعوذات.', 'لا تبن زواجا او مالا على الاحلام وتجاهل المفسرين المدفوعين.'], faq: [ { q: 'ما معنى الاحلام في الاسلام', a: 'ثلاثة انواع بشرى صادقة من الله وحلم مزعج من الشيطان وحديث نفس نهاري. واكثر الاحلام الواضحة من الثالث لا رسائل. ولا قاموس ثابت للرموز.' }, { q: 'ماذا افعل بعد الحلم السيئ', a: 'انفث عن يسارك ثلاثا وتعوذ بالله واقرأ دعاء الحلم السيئ وتحول الى جنبك وصل ان استيقظت ولا تخبر احدا فلا يضرك.' }, { q: 'هل تدل الاحلام على المستقبل او القرار', a: 'الرؤيا الصادقة تطمئن ولا تشريع فلا تبن عليها زواجا او طلاقا او مالا. واستعمل الاستخارة والمشورة واعتبر المفسرين المدفوعين دجلا.' } ], aliasesAr: ['تفسير الاحلام في الاسلام', 'ماذا تفعل بعد الكابوس'] },
  'halal-food-guide': { title: 'قواعد الطعام الحلال ما يجوز للمسلم اكله', intro: 'قواعد الطعام الحلال ببساطة ما يجعل اللحم حلالا وقراءة الملصقات للمواد المحرمة وحكم الماكولات البحرية والتخدير والاكل خارج البيت دون قلق.', sections: [ { h: 'قائمة المحرم والذبح الحلال', ps: ['قائمة القران المحرمة قصيرة ومطلقة الميتة والدم المسفوح ولحم الخنزير وما اهل لغير الله والمسكرات وبالاجماع ذوات الانياب والطيور ذات المخالب في الايات 2:173 و5:3. وما عداها حلال بالاصل ومنه كل الماكولات البحرية عند الجمهور. والكحول حرام بكل قدر مسكر والتلوث غير المقصود بادوات مشتركة عذر مشقة لا اثم بعد الاحتياط المعقول.', 'واللحم الحلال يشترط ذابحا مسلما مع ذكر اسم الله وقطع الاوداج ونزف الدم والذبح الالي والتخدير قبله محل خلاف فاقبل جهة توثيق حلال تثق بها واقرأ معيارها في التخدير القاتل او القابل للافاقة واتبع علماءك لا التغليف وحده. وعند الشك الحقيقي بلا توثيق اترك ما يريبك واختر خيارا نباتيا او موثقا.'] }, { h: 'الملصقات والاكل خارجا وعلاج القلق', ps: ['اولويات قراءة الملصقات الجيلاتين مصدر خنزير او بقر او سمك والمستحلبات والانزيمات حيوانية او نباتية والمنفحة في الجبن ونكهات الفانيليا والكحول والنكهات الطبيعية في الاسواق الصارمة واحفظ قائمة مكونات حلال موثوقة بدل البحث كل مرة. وخارج البيت اسال مرة بهدوء هل اللحم معتمد وهل الدجاج مخدر وعند الاجابة المبهمة اطلب ماكولات بحرية او نباتية دون احراج.', 'وعلاج القلق هو التوازن فالعلماء يفرقون بين الوسوسة والتقوى فاذا كان خوف المكونات يفسد الوجبات فهو الوسواس فعالجه لا تغذيه. قل بسم الله وخذ بالاسباب المعقولة وكل شاكرا وادع بادعية قبل الاكل وبعده. فالاكل الحلال طاعة مفرحة لا رعب تحقيقي.'] } ], steps: ['تعلم قائمة المحرم القصيرة الميتة والدم والخنزير وما اهل لغير الله والمسكر.', 'اشتر اللحم من توثيق تثق به وتحقق من معيار التخدير.', 'اقرأ الملصقات للجيلاتين والانزيمات والمنفحة ونكهات الكحول.', 'خارج البيت اسال مرة بهدوء وعند الابهام اختر بحريا او نباتيا.', 'قل بسم الله وكل شاكرا واعتبر هوس المكونات وسوسة.'], faq: [ { q: 'ما الطعام الحرام في الاسلام', a: 'الميتة والدم المسفوح والخنزير وما اهل لغير الله والمسكرات مع ذوات الانياب والمخالب وما عداها ومنه كل البحري عند الجمهور حلال بالاصل.' }, { q: 'هل التخدير جائز في الذبح الحلال', a: 'فيه خلاف فالتخدير القابل للافاقة يقبله كثير من الموثقين والقاتل مرفوض. تحقق من معيار جهتك واتبع العلماء الموثوقين.' }, { q: 'كيف اكل حلالا في السفر او المطاعم', a: 'اسال مرة عن التوثيق وعند الشك اطلب بحريا او نباتيا وقل بسم الله فالتلوث غير المقصود بعد الاحتياط المعقول معفو لا اثم.' } ], aliasesAr: ['احكام الطعام الحلال', 'شروط اللحم الحلال'] },
  'sujood-as-sahw-guide': { title: 'سجود السهو طريقة جبر النسيان في الصلاة', intro: 'طريقة سجود السهو عند زيادة او نقص او شك في الركعات سجدتان تجبرانها. تعلم متى يجب وطريقته وخلاف المذاهب.', sections: [ { h: 'متى يجب السهو ومتى لا يجب', ps: ['سجود السهو يجبر ثلاثة اخطاء زيادة كركعة او سجدة زائدة او ترك واجب كالتشهد الاول او شكا حقيقيا في عدد الركعات. قال النبي اذا شك احدكم فليبن على ما استيقن وليسجد سجدتين قبل السلام. اما ترك ركن كركعة كاملة او ركوع او سجود فلا يجبره السهو بل تعاد تلك الركعة.', 'ولا سجود لشرود ذهن يسير مع اتمام الاركان ولا لشك بعد انتهاء الصلاة ولا لوسوسة تطلب التكرار فهي تهمل حكما لا تجبر بسجود. وسهو واحد بسجدتين يكفي لكل اخطاء صلاة واحدة واخطاء الماموم يحملها الامام فلا يسجد وحده.'] }, { h: 'الطريقة وخلاف المذاهب', ps: ['الطريقة قرب نهاية الصلاة اسجد سجدتين قل فيهما سبحان ربي الاعلى ثم اجلس واقرأ التشهد وسلم. والحنفية بعده يسلم ثم يسجد ثم يتشهد ويسلم والشافعية والحنابلة قبله غالبا والمالكية يفرقون الزيادة بعد والنقص قبل. وكلها معمول بها فاتبع مذهبك ومعلمك دون جدال.', 'وعند الشك في العدد ابن على الاقل المتيقن فالشك بين 3 و4 يعني اليقين 3 فاكمل الى 4 واسجد. وان كان الشك عادة كل صلاة فهو وسوسة فاعمل باول ترجيح وارفض التكرار فغاية الشيطان جعل العبادة لا تطاق لا جعلها دقيقة.'] } ], steps: ['حدد الخطأ زيادة او ترك واجب او شك حقيقي في العدد.', 'ان تركت ركنا فاعد تلك الركعة فالسهو وحده لا يجبره.', 'عند الشك ابن على الاقل المتيقن واكمل الصلاة.', 'اسجد سجدتين بسبحان ربي الاعلى واجلس وتشهد وسلم.', 'الماموم خلف الامام لا يفعل شيئا فسهو الامام يكفيه.'], faq: [ { q: 'كيف تؤدي سجود السهو', a: 'اسجد سجدتين قرب نهاية الصلاة بسبحان ربي الاعلى واجلس وتشهد وسلم. والحنفية بعده والشافعية والحنابلة قبله فاتبع مذهبك.' }, { q: 'متى يجب سجود السهو', a: 'بعد زيادة فعل او ترك واجب كالتشهد الاول او شك حقيقي في العدد. وترك الركن يعيد الركعة والشك العابر والوسوسة لا شيء فيهما.' }, { q: 'اشك في عدد الركعات دائما ماذا افعل', a: 'ابن على الاقل المتيقن واتم مع السهو. وان كان كل صلاة فهو وسوسة فاعمل باول ترجيح وارفض التكرار وراجع دليل الشك.' } ], aliasesAr: ['طريقة سجود السهو', 'الشك في عدد الركعات'] },
  'prayer-mistakes-common': { title: 'اخطاء شائعة في الصلاة وكيف تصلحها', intro: 'اخطاء شائعة في الصلاة تبطلها او تضعفها الاسراع دون طمانينة وخطأ الركوع والسجود وسبق الامام وانشغال الهاتف مع الاصلاح.', sections: [ { h: 'اخطاء تمس الصحة', ps: ['الاسراع دون طمانينة وهي السكون في كل ركن يبطل الصلاة عند الجمهور فقد امر النبي المسيء صلاته ارجع فصل فانك لم تصل. فاثبت في كل وضع حتى تقول الذكر ثلاثا فعلا. وسبق الامام بركوع او رفع قبله منهي بشدة فاتبع الامام ولا تتقدمه.', 'والصلاة دون وضوء صحيح او قبل دخول الوقت وكشف العورة كقميص يرتفع في السجود للرجال وحجاب ينزلق للنساء والمرور دون سترة في الزحام كلها تمس الصحة. فاصلح الاسباب مرة تعلم الوضوء وتحقق من الوقت باداة الاوقات والبس للسجود لا للمراة وضع سترة في الاماكن المفتوحة.'] }, { h: 'اخطاء تمس الاجر', ps: ['النظر حولك او الى الاعلى والبصر محله السجود والعبث وتشبيك الاصابع والنظر في الهاتف والصلاة حيث يمر الناس والاسراع بالقراءة حتى تضيع الحروف كلها تنقص صلاة صحيحة. والهاتف يستحق التنبيه اصمته قبل التكبير فرنينه يقطع صلاتك والصف كله. والثوم والبصل النيئ قبل المسجد يؤذي الملائكة والجيران.', 'وصفوف الرجال والنساء ومزاحمة المتاخر ليدرك الركعة والكلام بعد الاقامة من القائمة. وانصح غيرك بلطف بعد الصلاة لا بغضب اثنائها فالمسجد الذي يعلم برفق يمتلئ. واجمع مع هذا الدليل دليلي خطوات الصلاة والاذكار لتعيد بناء الصلاة من صحيحة الى جميلة.'] } ], steps: ['تمهل واثبت في كل ركن حتى تقول الذكر بهدوء ثلاثا.', 'اتبع الامام ولا تركع ولا ترفع ولا تسجد قبله.', 'تحقق من الوضوء والوقت وستر العورة قبل كل صلاة.', 'اصمت الهاتف واجعل بصرك في السجود واستعمل سترة.', 'تعلم اصلاحا واحدا اسبوعيا وعلم اسرتك بلطف دون توبيخ.'], faq: [ { q: 'هل السرعة تبطل الصلاة', a: 'نعم عند الجمهور فترك الطمانينة في الركوع والقيام والسجود والجلوس يبطل الصحة. فاثبت في كل ركن حتى تقول الذكر ثلاثا.' }, { q: 'هل يحرم التقدم على الامام', a: 'التقدم العمد منهي بشدة فاتبع حركاته. والتاخر اليسير جائز اما السبق فهو الذنب.' }, { q: 'هل اصلي والهاتف في جيبي', a: 'نعم ان كان صامتا تماما لكن الرنين يزعج الجماعة كلها. فاصمته او اغلقه قبل التكبير كل مرة.' } ], aliasesAr: ['اخطاء الصلاة الشائعة', 'الخشوع وسبق الامام'] },
  'waswasa-doubts-worship': { title: 'الوسوسة في الوضوء والصلاة الشكوك وعلاجها', intro: 'الوسوسة في الصلاة والوضوء شكوك لا تنتهي في الريح والقطرات والحروف والركعات. والعلاج اليقين لا يزول بالشك والاهمال للوسواس.', sections: [ { h: 'القاعدة الكبرى وميادينها الشائعة', ps: ['القاعدة الكبرى لكل حالة اليقين لا يزول بالشك. فقد توضأت فاحساس الريح دون صوت او ريح لا يغير شيئا فقد امر النبي الا يخرج حتى يسمع صوتا او يجد ريحا. وقطرات بعد البول والشك في غسل عضو او قراءة الفاتحة او عدد الركعات جوابه واحد اعمل بالمتيقن واطرح الوسوسة.', 'واعرف العدو المسمى خنزب وهو شيطان الصلاة فالعلاج التعوذ والنفث عن اليسار ثلاثا عند هجومه. وصاحب السلس او الريح الدائم له رخصة لا لعنة فبعد مراجعة الطبيب توضأ مرة لكل وقت وصل دون تكرار فتكرار الوضوء خمس مرات هو المرض لا التقوى.'] }, { h: 'خطة العلاج الناجحة', ps: ['اولا تعلم الحكم مرة من عالم ثم توقف عن البحث فالتفتيش القهري عن الفتاوى يغذي الوسوسة. وثانيا حدد سقفا وضوء واحد وصلاة واحدة وقراءة واحدة للاية ولا تكرار والتزم به رغم القلق فسيزول خلال اسابيع. وثالثا سمها بصوت هذا خنزب ساتجاهله فالتسمية تكسر وهم التقوى الكاذبة. ورابعا لا تترك الصلاة والجماعة بسبب الشكوك فغاية الموسوس ابعادك عن العبادة.', 'وخامسا اجمع بين الروحي والطبي فالافكار القهرية المستمرة بنمط الوسواس القهري تستحق طبيبا مع الدعاء فالاسلام يعترف بالدواء سببا من الله. واقرأ دعاء خنزب واذكار الصباح والمساء والزم صحبة صالحة وقس التقدم بالشهور بتكرار اقل وصلاة اهدأ.'] } ], steps: ['طبق القاعدة الكبرى اليقين وضوء تم وفعل تم يغلب كل احساس.', 'حدد سقفا وضوء واحد وقراءة واحدة ولا تكرار والتزم به.', 'عند الهجوم اثناء الصلاة تعوذ وانفث يسارا 3 واكمل دون اعادة.', 'توقف عن تتبع الفتاوى القهري وتعلم الحكم مرة من عالم.', 'ان استمر النمط شهورا فراجع طبيبا مع الدعاء والاذكار.'], faq: [ { q: 'احس بخروج ريح اثناء الصلاة دون يقين هل انتقض وضوئي', a: 'لا فالاحساس دون صوت او ريح مؤكد لا يغير شيئا فاكمل صلاتك. فلا ينقض الوضوء الا اليقين.' }, { q: 'كيف اوقف تكرار الوضوء والركعات من الشك', a: 'حدد سقفا وضوء واحد ولا اعادة والتزم به رغم القلق وسم الوسواس خنزب وتجاهله. فالتكرار يغذيه والحد يجوعه.' }, { q: 'هل الوسوسة علامة ضعف ايمان', a: 'بالعكس فقد شكا الصحابة منها وسماها النبي صريح الايمان فالشيطان يهاجم قلبا فيه ما يسرق. وكره الوساوس نفسه ايمان.' } ], aliasesAr: ['علاج الوسوسة في الصلاة', 'شكوك الوضوء والريح'] },
  'qasr-jama-travel-sick-prayer': { title: 'القصر والجمع الصلاة في السفر والمرض', intro: 'طريقة صلاة القصر يقصر المسافر الصلوات الرباعية الى اثنتين ويجمع الظهر مع العصر والمغرب مع العشاء. مع الصلاة جالسا وفي السرير والمستشفى.', sections: [ { h: 'القصر والجمع', ps: ['السفر المبيح للرخصة نحو 80 الى 85 كم ذهابا مع نية اقامة اقل من نحو 15 يوما عند الحنفية وغيرهم بالعرف والحاجة وفي السفر الصحيح تصبح الصلوات الرباعية الظهر والعصر والعشاء ركعتين والفجر والمغرب بلا تغيير. ومن صلى خلف مقيم اتمه ومن ام المقيمين قصر واتموا بعده. وقضاء صلاة السفر في الحضر والعكس حسب وقت الاصل بتفصيل المذاهب.', 'والجمع يضم الظهر مع العصر والمغرب مع العشاء في وقت احداهما بالنية عند الحاجة الحقيقية سفر او مطر شديد او الحج في عرفة ومزدلفة او مرض او ضرورة حسب المذهب. والحنفية يقصرون الجمع غالبا على الحج والجمهور يوسعونه. ولا تجمع الفجر مع شيء ولا العصر مع المغرب وحافظ على الترتيب واسال العلماء في الحالات المزمنة.'] }, { h: 'صلاة المريض جالسا وفي السرير والعمل', ps: ['المرض لا يلغي الصلاة بل يغير هيئتها فصل قائما والا جالسا والا على جنب باتجاه القبلة والا على ظهر مع رفع الراس واومئ بالراس للركوع والسجود بعمق اكبر للسجود عند العجز. ومريض المستشفى يتيمم بوسادة غبار او جدار عند ضرر الماء ويصلي في السرير بثوب طاهر ويجمع عند تفرق اليوم فلا مريض واع يعفى من الصلاة.', 'وفي العمل او الدراسة الصلوات فرض لا يقبل التفريط فاستعمل الاستراحات وركنا هادئا وسجادة سفر واجمع في البيت حيث يجوز بدل الترك. وصلاة الجمعة تحتاج ترتيبا مع صاحب العمل لا استقالة متسرعة فاكثر الاعمال تقبل غداء مطولا مرة. وما فات من جراحة او اغماء يقضى حسب دليل القضاء اما الترك العمد للعمل فدين لا يبرره راتب.'] } ], steps: ['في السفر الصحيح نحو 80 كم واقامة قصيرة اقصر الظهر والعصر والعشاء الى ركعتين.', 'اجمع الظهر مع العصر او المغرب مع العشاء في وقت احداهما عند الحاجة.', 'خلف مقيم اتم الصلاة واماما مسافرا اقصر وليتموا بعدهم.', 'عند المرض قائما والا جالسا والا مستلقيا واومئ وتيمم ان ضر الماء.', 'في العمل رتب الاستراحات واحمل سجادة ولا تبع فرضا لاجل وردية.'], faq: [ { q: 'كيف تصلي صلاة القصر', a: 'في السفر الصحيح صل الظهر والعصر والعشاء ركعتين بدل اربع والفجر والمغرب بلا تغيير. وخلف مقيم صل تماما.' }, { q: 'اي الصلوات تجمع', a: 'الظهر مع العصر والمغرب مع العشاء في وقت احداهما في سفر او مرض او حاجة حسب المذهب. والفجر لا يجمع ابدا.' }, { q: 'كيف تصلي وانت مريض في السرير', a: 'اجلس ان قدرت والا فاستلق باتجاه القبلة واومئ بالراس بعمق اكبر للسجود. وتيمم ان ضر الماء. فما دام الوعي فالصلاة واجبة.' } ], aliasesAr: ['احكام قصر الصلاة في السفر', 'الجمع بين الصلاتين وصلاة المريض'] },
  'daily-sunnah-rawatib': { title: 'السنن اليومية الرواتب دليل 12 ركعة', intro: 'السنن 12 الراتبة التي تبني بيتا في الجنة اثنتان قبل الفجر واربع قبل الظهر واثنتان بعده واثنتان بعد المغرب واثنتان بعد العشاء مع بيان الاكد.', sections: [ { h: 'الاثنتا عشرة وترتيبها', ps: ['من صلى اثنتي عشرة ركعة سنة يوميا بنى الله له بيتا في الجنة اثنتان قبل الفجر واربع قبل الظهر واثنتان بعده واثنتان بعد المغرب واثنتان بعد العشاء. ومنها الاكد ركعتا الفجر فهما خير من الدنيا وما فيها ولم يتركهما النبي حضرا ولا سفرا وبقية السنن تركها في السفر. فوظائفها تختلف فسنتا الفجر والظهر مؤكدتان والمجموع الكامل هو مجموعة بيت الجنة.', 'وبعد الاثنتي عشرة نوافل غير مؤكدة اربع قبل العصر وركعتان قبل المغرب وركعتان قبل العشاء لمن شاء وتحية المسجد ركعتين عند الدخول وركعتان بعد الوضوء التي ادخلت بلالا الجنة. فاجعل الاثنتي عشرة هيكلا يوميا والزوائد قوة.'] }, { h: 'متى واين وكيف تثبت عليها', ps: ['صل السنن في البيت ما امكن فافضل صلاة المرء في بيته الا المكتوبة واجعل المسجد للفرض والبيت مضيئا بالنفل وفيه تربية الاولاد بالقدوة. واذا اقيمت الصلاة فاترك السنة والحق بالفرض فلا سنة تنافس الجماعة. وما فات من الرواتب يقضى في نفس اليوم فقد قضى النبي سنتي الظهر بعد العصر واسال العلماء عن سعة الوقت.', 'وابن العادة سلما ثبت ركعتي الفجر اربعين يوما ثم اضف المغرب والعشاء ثم مجموعة الظهر واربط كل سنة بفرضها مع منبهات اوقات الصلاة. والمسافر يحافظ على الاقل على الفجر والوتر والمريض يصلي جالسا باجر النية الكامل. فاثنتا عشرة ركعة يوميا خير من قيام طويل متقطع.'] } ], steps: ['اثبت ركعتي الفجر اولا فلا تترك حضرا ولا سفرا.', 'اضف اثنتي المغرب واثنتي العشاء ثم الاربع قبل الظهر والثنتين بعده.', 'صل السنن في البيت واتركها فورا اذا اقيمت الصلاة.', 'اقض ما فات في نفس اليوم بدل الترك.', 'اضف الزوائد الاربع قبل العصر وتحية المسجد وسنة الوضوء بعد الثبات.'], faq: [ { q: 'ما السنن 12 التي تبني بيتا في الجنة', a: 'اثنتان قبل الفجر واربع قبل الظهر واثنتان بعده واثنتان بعد المغرب واثنتان بعد العشاء فمن حافظ عليها يوميا بني له بيت في الجنة.' }, { q: 'هل السنن في البيت ام المسجد', a: 'في البيت افضل الا الفرض فهي تملأ البيت عبادة وتربي الاولاد بالقدوة. والزم المسجد لكل صلاة واجبة.' }, { q: 'هل تقضى السنن الفائتة', a: 'نعم في نفس اليوم فقد قضى النبي سنتي الظهر بعد العصر. والقضاء خير من الترك واسال العلماء عن السعة.' } ], aliasesAr: ['السنن الرواتب 12 ركعة', 'سنة الفجر وفضلها'] },
  'shirk-types-explained': { title: 'الشرك في الاسلام الاكبر والاصغر والخفي', intro: 'ما هو الشرك في الاسلام الذنب الذي لا يغفر بلا توبة الشرك الاكبر والاصغر كالرياء والخفي مع امثلة يومية والحماية.', sections: [ { h: 'الشرك الاكبر صرف العبادة لغير الله', ps: ['الشرك صرف العبادة لغير الله وهو الذنب الذي لا يغفره الله لمن لقيه دون توبة في الاية 4:48 لانه يقلب غاية الخلق. والشرك الاكبر يخرج من الاسلام كدعاء الاولياء والقبور والذبح والنذر لغير الله واعتقاد النفع والضر في التمائم والمنجمين استقلالا او طاعة جهة في مخالفة شرع الله الواضح كانها تشرع. ومن اقنعته الحديثة السياحة القبورية لطلب الولد وتطبيقات التنجيم والابراج مع المحافظة على الصلوات.', 'والمعيار هو العبادة فالدعاء هو العبادة فينقل الدعاء للميت شركا اكبر مهما قيل في النية. وانصح غيرك بحكمة وقران فاكثر الواقعين ورثوا العادة ببراءة واثبت على التوحيد الخالص اياك نعبد واياك نستعين التي تتلوها سبع عشرة مرة يوميا.'] }, { h: 'الشرك الاصغر والخفي واصنام القلب', ps: ['الشرك الاصغر لا يخرج من الاسلام لكنه يفسد العمل كالرياء وتحسين الصلاة لوجود الناظرين والحلف بغير الله وقول لولا الله وانت بتسوية المخلوق مع الخالق. وقد خاف النبي الرياء على امته اكثر من الدجال وعلاجه السر في العبادة كصدقة الخفاء وقيام الليل وتجديد النية اثناء العمل.', 'والشرك الخفي ادق كدبيب النملة السوداء على الصخرة السوداء في الليلة المظلمة كالاعتماد على الاسباب وحدها والدواء شفاني دون ذكر الله وحب المال والجاه حبا تعبديا او طاعة الهوى ضد الحق المعلوم. ودرعه دعاء الاستعاذة من الشرك وعادة اللسان ما شاء الله هذا من فضل الله عبر كذا. فالتوحيد المصقول يوميا يغلب كل ظلمة.'] } ], steps: ['وجه كل دعاء ونذر وذبح وتوكل مطلق الى الله وحده.', 'طهر الشرك الاصغر اعبد سرا واحلف بالله فقط وصحح قول الله وانت.', 'راقب الخفي وانسب الفضل الى الله اولا في كل نعمة وسبب.', 'اقرأ دعاء الاستعاذة من الشرك يوميا وعلم الاولاد اياك نعبد بمعناها.'], faq: [ { q: 'ما هو الشرك بكلمات بسيطة', a: 'اعطاء غير الله ما يخصه وحده كالعبادة والدعاء والتوكل المطلق والتشريع. فالاكبر يخرج من الاسلام والاصغر كالرياء والخفي يفسد العمل.' }, { q: 'هل سؤال الاولياء والقبور شرك', a: 'نعم فالدعاء عبادة وصرفه للميت شرك اكبر مهما قيل في النية. واسال الله مباشرة واكرم الصالحين باتباعهم لا بدعائهم.' }, { q: 'كيف احمي نفسي من الشرك الخفي', a: 'اقرأ دعاء الاستعاذة من الشرك يوميا وانسب الفضل الى الله اولا واعبد سرا احيانا وجدد النية كثيرا.' } ], aliasesAr: ['ما هو الشرك وانواعه', 'الرياء والشرك الخفي'] },
  'signs-day-of-judgment': { title: 'علامات القيامة الصغرى والكبرى شرح موثوق', intro: 'علامات القيامة شرح موثوق العلامات الصغرى المشهودة والعشر الكبرى من الدجال الى طلوع الشمس من مغربها وكيف تستعد.', sections: [ { h: 'العلامات الصغرى العالم الذي نعرفه', ps: ['اخبر النبي بعلامات صغرى كانها اخبار اليوم ضياع الامانة والعلم وشيوع الربا والزنا والمعازف والخمور والتطاول في البنيان في الصحارى وتقارب الزمان وتزويق المساجد مع فراغ القلوب وتنزل الفتن كالمطر. ووظيفتها ليست تحديد الموعد الذي اختص الله بعلمه في الاية 7:187 بل الاستعجال فكل علامة تحققت منبه شخصي.', 'وتعامل معها تشخيصا لا تسلية فمشاهدة مقاطع النهايات مع تضييع الفجر يقلب غايتها. وقد سمعها الصحابة فقابلوها بعبادة وصدقة وصلح فمحتوى التخويف الذي ينتج خوفا دون صلاة فشل في مهمته. ولا يملك عالم او صاحب منام تحديد السنة فكل مدع لتاريخ معين يلحق بسلسلة طويلة من المردودين.'] }, { h: 'العشر الكبرى بالترتيب والاستعداد الوحيد', ps: ['تاتي العلامات الكبرى متتابعة كخرز انقطع سلكه الدجال المسيح الكذاب الاعور مكتوب بين عينيه كافر وايام فتنته اربعون يقتله عيسى في لد ثم نزول عيسى بن مريم يحكم بالاسلام ثم ياجوج وماجوج ينتشرون فيهلكهم الله ثم ثلاثة خسوف في المشرق والمغرب وجزيرة العرب ثم الدخان ثم طلوع الشمس من مغربها فيغلق باب التوبة ثم الدابة تميز الجباه ثم نار تسوق الناس الى المحشر.', 'واحفظ اول عشر ايات من الكهف حماية من الدجال وحافظ على الجمعة وعش تائبا يوميا بسداد الديون وحفظ الصلوات وطلب المغفرة ليلا فطلوع الشمس من المغرب ينهي قبول التوبة. وعلم الاولاد الترتيب قصة لا رعبا فكل علامة تنتهي الى عدل الله وجنته فالمؤمن يلقى الساعة بوضوء وصلاة وصحيفة نظيفة.'] } ], steps: ['تعلم الصغرى دافعا شخصيا لا تسلية وتحديد مواعيد.', 'احفظ العشر الكبرى بالترتيب بدءا بالدجال.', 'احفظ اول عشر ايات من الكهف حماية من الدجال.', 'عش تائبا ديون مسددة وصلوات محفوظة واستغفار ليلي.', 'علم الترتيب للاولاد قصة مفعمة بالامل لا رعبا.'], faq: [ { q: 'ما العلامات الكبرى للقيامة', a: 'الدجال ونزول عيسى وياجوج وماجوج وثلاثة خسوف والدخان وطلوع الشمس من مغربها والدابة ونار المحشر عشر علامات متتابعة.' }, { q: 'ما الصغرى التي ظهرت', a: 'ضياع الامانة والعلم وشيوع الربا والفواحش والتطاول في البناء وتقارب الزمان وزخرفة المساجد مع فراغ القلوب فاكثر الصغرى الكلاسيكية ظاهرة.' }, { q: 'كيف احمي اسرتي من الدجال', a: 'احفظ اول عشر ايات من الكهف وكررها وحافظ على الصلاة والجماعة وعلم الاولاد الترتيب فالحماية عبادة لا مخابئ.' } ], aliasesAr: ['علامات الساعة الصغرى والكبرى', 'الدجال وياجوج وماجوج بالترتيب'] },
  'grave-barzakh-after-death': { title: 'الحياة بعد الموت القبر والبرزخ واليوم الاخر', intro: 'ماذا يحدث بعد الموت في الاسلام رحلة الروح واسئلة القبر ونعيم البرزخ وعذابه والبعث والاعمال التي تنفع بعد الدفن.', sections: [ { h: 'الرحلة الروح واسئلة القبر والبرزخ', ps: ['عند الموت تخرج روح المؤمن برفق وتنزع روح الجاحد في الايات 79:1 الى 5 ثم تصعد مكرمة او تطرح مهانة ثم تعود لسؤال القبر. ويسال كل مدفون من ربك وما دينك ومن هذا الرجل محمد فيجيب المؤمن بيسر وينام في قبر مفتوح على الجنة ويتلعثم المنكر لا ادري فيضيق ويعرض على النار غدوا وعشيا في الاية 40:46.', 'والبرزخ حياة فاصلة حتى البعث في الاية 23:100 وهي نعيم او عذاب فالشهداء احياء يرزقون في 3:169 وكان النبي يستعيذ من عذاب القبر في كل تشهد اخير. وزيارة القبور تذكر الاحياء وتصل الاموات الصدقة والدعاء لا القراء المستاجرون وولائم الايام والنواح فالدموع الهادئة جائزة وتمزيق الثياب محرم.'] }, { h: 'البعث والحساب والاعمال الثلاثة الباقية', ps: ['ثم النفخ في الصور فيقوم الناس حفاة ليوم مقداره خمسون الف سنة في الاية 70:4 والكتب باليمين او الشمال والموازين تزن مثاقيل الذر في 99:7 و8 والحوض يسقي الثابتين والصراط ادق من الشعر واحد من السيف يعبر بسرعة العمل. والشفاعة باذن الله يقودها محمد للعصاة من امته والجنة والنار داران واعيتان خالدتان لا موت فيهما.', 'وثلاثة اعمال تبقى بعد الدفن وهي مشروع كل مسلم الان صدقة جارية كالابار والمساجد وصناديق العلم وعلم نافع كقران معلم وتوجيه مؤلف وطلاب مربين وولد صالح يدعو. فافتح من كل واحد قبل الثلاثين صدقة شهرية وتعليم سورة لشخص وتربية اولاد يحفظون اجوبة القبر. فالموت ليس نهاية الكسب بل نهاية البدء.'] } ], steps: ['تعلم اجوبة القبر الثلاثة الرب الله والدين الاسلام والرجل محمد.', 'استعذ من عذاب القبر في كل جلوس اخير في الصلاة.', 'زر القبور للتذكير وارسل للاموات صدقة ودعاء لا ولائم ونواحا.', 'افتح الثلاثة الباقية مبكرا صدقة جارية وعلما معلما وولدا صالحا.', 'عش مستحضرا البعث وسامح وسدد الديون قبل نومك ليلا.'], faq: [ { q: 'ماذا يحدث بعد الموت في الاسلام', a: 'تصعد الروح او تطرح ثم تعود لسؤال القبر عن الرب والدين والنبي ثم نعيم البرزخ او عذابه حتى البعث والحساب والجنة او النار الابدية.' }, { q: 'ما الاسئلة الثلاثة في القبر', a: 'من ربك وما دينك ومن هذا الرجل محمد فيجيب المؤمن الله والاسلام ورسول الله ويخفق غيره. والاعداد عقيدة معاشة لا حفظ الفاظ.' }, { q: 'اي الاعمال تنفع بعد الموت', a: 'صدقة جارية وعلم نافع ودعاء ولد صالح مع حج او دين يقضى عن الميت. والنواح وولائم الايام لا تضيف شيئا.' } ], aliasesAr: ['ماذا بعد الموت وعذاب القبر', 'اسئلة القبر والبرزخ'] },
  'music-singing-ruling': { title: 'هل الموسيقى حرام في الاسلام الحكم الصادق', intro: 'هل الموسيقى حرام في الاسلام حكم الجمهور واستثناء الاقلية وما اتفق عليه من الفحش وترك الصلاة وخطة عملية للترك.', sections: [ { h: 'الحكم الجمهور والاقلية والمتفق عليه', ps: ['جمهور العلماء عبر المذاهب على تحريم المعازف مستندين الى اية لهو الحديث في 31:6 التي فسرها ابن عباس وابن مسعود بالغناء وحديث البخاري في من يستحلون الحر والحرير والخمر والمعازف وما نقله الفقهاء من اجماع. واقلية كابن حزم والغزالي في نطاق وبعض المعاصرين تجيز غير الفاحش دون اسراف الات فاعرف القولين ثم رجح فالجمهور احوط لعادة تاكل وقت الصلاة والقران.', 'والمتفق عليه اوسع من الخلاف فالنشيد الصوتي وحده بمعنى طيب جائز عند الجميع والكلمات الفاحشة او الجنسية حرام بالات او دونها وكل سماع يسقط الصلوات او يغذي الشهوات او يمجد المعصية حرام بثمرته. فاحكم على قائمتك بالثمرة اولا والالة ثانيا فايقاع حلال يسقط الفجر حرام عليك مهما بحثت عن فتوى.'] }, { h: 'خطة الترك والبدائل الحلال', ps: ['الترك المفاجئ يفشل فاستبدل بدلا منه. في الاسبوع الاول احذف اعلى خمسة فاحشة واسمع القران مع الترجمة او السيرة في الطريق. وفي الثاني ازل الموسيقى من الرياضة والاعمال المنزلية واستبدل نشيدا او صمتا مع ذكر وعداد التسبيح. وفي الثالث نظف الحسابات ذات التشغيل التلقائي فالخوارزمية هي الموزع. وتوقع ضيق انسحاب اياما ثم يزول مع تاقلم القلب.', 'والافراح تحتاج تخطيطا لا وعظا فاعرض تنظيم الصوت واحضر قائمة نشيد ودف فالدف في الاعراس والعيد جائز ثابت وتخرج بهدوء ان بدأ الحرام بدل المواجهة. واملا اذان الاولاد قبل الصناعة بقران السيارة ومكافات الحفظ وصحبة صالحة واسال عالما عن حالتك واعمل يوم تعلم.'] } ], steps: ['راجع قائمتك بالثمرة صلوات فائتة وشهوات وفحش واحذف الاسوأ اليوم.', 'استبدل الطريق بقران مع ترجمة او صوت السيرة.', 'نظف الخلاصات ذات التشغيل التلقائي واستبدل الرياضة بنشيد او ذكر.', 'استعمل الدف الجائز في الاعراس والعيد بفرح حلال.', 'اسال عالما عن حالتك واعمل يوم تعلم.'], faq: [ { q: 'هل الموسيقى حرام في الاسلام', a: 'الجمهور على تحريم المعازف لاية 31:6 بتفسير الصحابة وحديث المعازف واقلية تجيز غير الفاحش. والفحش وما يسقط الصلاة حرام بالاتفاق.' }, { q: 'هل النشيد دون موسيقى حلال', a: 'نعم النشيد الصوتي الطيب جائز عند الجميع. والدف في الاعراس والعيد ثابت في الصحيحين.' }, { q: 'كيف اترك ادمان الموسيقى', a: 'استبدل لا تحذف فقط قران مع ترجمة للطريق ونشيد للرياضة وتنظيف الخلاصات وصحبة صالحة. وتوقع ضيق ايام ثم يتاقلم القلب.' } ], aliasesAr: ['حكم الغناء والمعازف', 'النشيد الحلال وترك الموسيقى'] },
  'gaming-movies-entertainment': { title: 'الالعاب والافلام والتواصل ضوابط اسلامية', intro: 'هل الالعاب حرام وهل الافلام مباحة اطار الترفيه في الاسلام خمسة اختبارات للالعاب والافلام والتمرير اللانهائي مع خطة اعادة ضبط.', sections: [ { h: 'اختبارات الحدود الخمسة', ps: ['يحكم الاسلام على الترفيه بالمحتوى والنتيجة لا بالفئة الاول العقيدة فما يمجد الشرك او السحر قوة او يسخر من الله والانبياء يسقط فورا. والثاني الفحش فالشخصيات الجنسية والمشاهد القريبة من الاباحية وقصص المواعدة تطبيع لزنا العين والقلب والاية 24:30 تامر بغض البصر عن الشاشات ايضا. والثالث العبادة فما ياكل الصلوات او الصوم او القران عادة فهو حرام بثمرته ولو كان نظيفا.', 'والرابع المال والعقل فاليات القمار كالصناديق المشتراة بمال حقيقي والمراهنة حرام كالميسر والرعب والدم يفسد امانة النفس. والخامس الصحبة والكلام فدردشة السباب والغيبة تحصي ذنوبا لكل رسالة والاية 49:12 تشمل الدردشة ايضا. فاللعبة الناجحة في الخمسة النظيفة المحدودة الوقت في المباح وما عداها فاكثر الالعاب المشهورة يسقط في اثنين على الاقل.'] }, { h: 'خطة اعادة الضبط العاب وافلام وتمرير', ps: ['للاعبين راجع مكتبتك بالاختبارات الخمسة الليلة واحذف اسوأ لعبتين وضع سقفا يوميا صارما مثلا 45 دقيقة بعد العشاء لا قبل الفجر بمؤقت ظاهر واستبدل التنافس المحموم برياضة او حلقات حفظ او مهارة. وللافلام راجع المحتوى مسبقا وتجنب الرومانسي تماما وشاهد مع الاسرة حيث يمنعك الحياء من الفحش واسال هل اشاهده مع امي وسيرة النبي مفتوحة فهو اختبار صادق.', 'وللمدمنين على التمرير دواء اشد فاحذف اسوأ تطبيق 30 يوما لا تخفف واحذف كل تنبيه غير بشري واخرج الهاتف من غرفة النوم واستعمل منبها عاديا واملا الساعة المستعادة بقران او رياضة او كسب. وتابع الثبات باداة تتبع الصلاة فانتظام العبادة مقياس نجاح الضبط. فالترفيه خادم ومتى نظم صلواتك صار سيدا.'] } ], steps: ['اعرض كل لعبة وفيلم وتطبيق على اختبارات الحدود الخمسة الليلة.', 'احذف اسوأ اثنين وحدد الباقي بمؤقت ظاهر.', 'احذف اسوأ تطبيق ادمانا 30 يوما واخرج الهاتف من الغرفة.', 'راجع الافلام مسبقا وتجنب الرومانسي وشاهد ما يصلح للاسرة.', 'املا الساعات بقران ورياضة وكسب وتابع انتظام الصلاة.'], faq: [ { q: 'هل الالعاب حرام في الاسلام', a: 'تنجح او تسقط بخمسة لا شرك ولا فحش ولا اكل للصلوات ولا قمار ولا كلام سيئ. واكثر المشهورة يسقط في اثنين واللعب النظيف المحدود هو المباح.' }, { q: 'هل يشاهد المسلم الافلام', a: 'المحتوى هو الفيصل فتجنب الجنسي والتجديف وتمجيد السحر تماما وراجع الباقي مسبقا واجعله مناسبا للاسرة ولا تدع الشاشة تزيح الصلاة.' }, { q: 'كيف اكسر ادمان الهاتف', a: 'احذف لا تخفف اسوأ تطبيق 30 يوما والغ التنبيهات غير البشرية واخرج الهاتف من الغرفة واملا الساعة بعبادة ورياضة وكسب.' } ], aliasesAr: ['حكم الالعاب والافلام', 'ادمان التواصل وعلاجه'] },
  'crypto-forex-trading-halal': { title: 'هل العملات الرقمية حلال التداول والفوركس والاسهم', intro: 'هل العملات الرقمية حلال وهل الفوركس جائز خريطة فقهية صادقة الملكية الفورية ضد الرافعة وفحص الاسهم الحلال ولماذا تفشل المضاربة اليومية.', sections: [ { h: 'العملات والفوركس وخط الرافعة', ps: ['انقسم العلماء المعاصرون ثلاثة في العملات نفسها مباحة كاصل رقمي له قيمة سوقية ومكروهة متسامح فيها للتقلب والجهالة ومحرمة لفرط الغرر بلا منفعة ذاتية. ولا فتوى واحدة ملزمة للامة فاسال العلماء عن عملتك واستعمالك بينما قواعد التداول ادناه تلزمك على كل راي.', 'والخط الواضح الرافعة والفائدة فالتداول بالهامش والعقود الاجلة والسواب الدائم ومعدلات التمويل وحسابات الفوركس بفائدة التبييت هياكل ربا وغرر محرمة بكل الاراء وملصق اسلامي او بدون سواب يحتاج تدقيقا شرعيا لا ثقة تسويقية. والشراء الفوري بملكية كاملة وتسوية فورية انظف صورة والتخزين بعائد محل خلاف بين مشاركة ربح وفائدة مقنعة والمضاربة اليومية مهنة تنهار الى مقامرة وادمان وترك صلاة فهي حرام بثمرتها ولو بدا العقد نظيفا.'] }, { h: 'فحص الاسهم الحلال وانضباط المستثمر', ps: ['واسهم الشركات المباحة تمر بفحص معتمد كمعيار هيئة المحاسبة الديون بفائدة والدخل بفائدة والايراد الحرام كلها دون نحو 5 بالمئة مع نسب سيولة ثم طهر الارباح بالتبرع بالجزء الحرام واد الزكاة بحاسبة زكاة الاستثمار. ومن اخفق في الفحص خرج وقول الجميع يشتريه لا يبيح حكما. وفصل الاستثمار الطويل في شركات حقيقية على مقامرة الرسوم فاخلاق السوق النبوية تكافئ التجارة الحقيقية لا المضاربة الصفرية.', 'وقواعد الانضباط لا تتاجر بدين او مال الايجار ولا رافعة ابدا وحدد المضاربة بجزء صغير من المال واتمت الزكاة سنويا واجعل فوات الصلاة قاطع التيار فمحفظة تسقط الفجر خاسرة في السجل الوحيد المهم. واكتب استراتيجيتك واعرضها على عالم مرة ثم نفذ دون تنقل بين الفتاوى حتى تتغير الظروف.'] } ], steps: ['افصل الاباحة واسال العلماء عن عملتك عن الية التداول وقواعدها.', 'تجنب كل رافعة وعقود وسواب وفائدة تبييت وملكية فورية فقط.', 'افحص الاسهم بمعيار شرعي وطهر الارباح واد الزكاة بالحاسبة.', 'لا تتاجر بدين وحدد المضاربة صغيرة وفوات الصلاة ينهي الجلسة.', 'اعرض استراتيجيتك على عالم مرة وتوقف عن التنقل بين الفتاوى.'], faq: [ { q: 'هل العملات الرقمية حلال', a: 'فيها خلاف مباحة ومتسامح فيها ومحرمة للغرر ولا اجماع ملزم. فاسال العلماء عن عملتك واستعمالك وتجنب بكل راي الرافعة والعقود والهياكل الربوية.' }, { q: 'هل تداول الفوركس حلال', a: 'الصرف الفوري بتسوية فورية جائز والفوركس بالرافعة مع فائدة التبييت محرم للربا والغرر. واكثر حسابات التجزئة تسقط في الثاني.' }, { q: 'كيف استثمر في الاسهم حلالا', a: 'اختر شركات مباحة تجتاز فحص الديون والدخل بنحو 5 بالمئة وطهر الجزء الحرام بالتبرع واد الزكاة سنويا واستثمر طويلا بدل المضاربة اليومية.' } ], aliasesAr: ['حكم العملات الرقمية والبيتكوين', 'حكم الفوركس والاسهم الحلال'] },
  'dogs-pets-in-islam': { title: 'الكلاب والحيوانات في الاسلام الاقتناء والطهارة', intro: 'هل الكلاب حرام في الاسلام اقتناؤها للحراسة والصيد والرعي جائز والتربية المنزلية وقواعد النجاسة وحديث الملائكة شرح مفصل.', sections: [ { h: 'ما يجوز وما يقيده الحديث', ps: ['الكلاب ليست حراما كخلق فقد كرم القران كلب الصيد وكلب اهل الكهف في 5:4 و18:18 واقتناؤها للصيد والرعي والحراسة والزراعة ومساعدة ذوي الاعاقة جائز صراحة. والقيد يستهدف التربية المنزلية دون حاجة فالملائكة لا تدخل بيتا فيه كلب واقتناء كلب دون حاجة ينقص الاجر يوميا قدر قيراط فهو ثمن مستمر غال لاجل تفضيل معيشي.', 'وقواعد النجاسة دقيقة لا فزع فلعاب الكلب نجس حكما فاغسل الاناء الملعوق سبعا اولاهن بالتراب وما يقوم مقامه بينما العلماء مختلفون في الشعر والجسد واللمس الجاف لا ينقل شيئا عند الجمهور. فكلب العمل الخارجي له تدبير واضح وكلب الغرفة له نصوص تمنعه. فاختر بوضوح دون تانيب للاخرين وانصح بالحديث وعش السنة ظاهرة.'] }, { h: 'القطط والطيور والاسماك والرحمة بكل كائن', ps: ['القطط حيوان منزلي محبوب فليست بنجسة والوضوء من انائها ثابت وكنية ابي هريرة تكرم هرته. والطيور والاسماك في اقفاص جائزة مع اطعام ورعاية فحديث تعذيب امرأة لحبسها قطة يضع المعيار فطعام كل محبوس وماؤه ومساحته امانة. والحيوانات البرية المفترسة او التي تعاني في الاسر تخفق في اختبار الرحمة فاتركها برية.', 'والرحمة نفسها عبادة باجر مسجل ففي كل كبد رطبة اجر ورجل دخل الجنة لسقي كلب. وتمتد الرحمة للضالة فاطعم كلاب الشوارع والقطط وادعم التعقيم وضع اوعية ماء في الصيف. فبيت المؤمن يستضيف القطط والاسماك والطيور برحمة وكلب الحراسة يعمل خارجا وقلبه رحمة للجميع فالقسوة باسم الله مخالفة لتعليم الرسول.'] } ], steps: ['اقتن الكلاب للصيد والحراسة والرعي والمساعدة خارجا لغرض.', 'تجنب كلب الزينة المنزلي دون حاجة لحديث الملائكة ونقص الاجر.', 'طبق النجاسة بدقة الاناء الملعوق يغسل سبعا واللمس الجاف لا شيء فيه.', 'اختر القطط او الطيور او الاسماك حيوانات منزلية مع رعاية امانة.', 'ارحم الضالة طعاما وماء فالرحمة اجر مسجل.'], faq: [ { q: 'هل الكلاب حرام في الاسلام', a: 'الكلاب كخلق ليست حراما واقتناؤها للصيد والحراسة والرعي والمساعدة جائز. والتربية المنزلية دون حاجة مقيدة لحديث الملائكة مع نقص يومي في الاجر.' }, { q: 'هل لعاب الكلب نجس وماذا لو لمسني', a: 'اللعاب نجس فاغسل الاناء الملعوق سبعا. ولمس الشعر الجاف لا ينقل شيئا عند الجمهور والملامسة الرطبة تغسل.' }, { q: 'هل القطط جائزة حيوانات منزلية', a: 'نعم بقوة فالقطط ليست بنجسة وتوضأ النبي من انائها وسمي ابو هريرة لهرته. فاطعمها وارعها كامانة.' } ], aliasesAr: ['حكم تربية الكلاب', 'نجاسة الكلب والقطط في الاسلام'] },
  'tattoos-piercing-ruling': { title: 'هل الوشم حرام الثقب وقواعد الجسد', intro: 'هل الوشم حرام في الاسلام حكم الوشم الدائم وحالة المسلم الجديد وصحة الوضوء والازالة مع الثقب والنمص وقواعد التجميل.', sections: [ { h: 'الوشم الدائم حكمه وعلله', ps: ['الوشم الدائم حرام بنص صريح فقد لعن النبي الواشمة والمستوشمة وصيغة اللعن علامة كبيرة وهو داخل في تغيير خلق الله في الاية 4:119. وعلل العلماء متقاربة حقن صبغ نجس تحت الجلد والم بلا حاجة وتغيير دائم دون حاجة وتشبه بثقافات فاسدة وكل واحدة تكفي ومجموعها يغلق الباب. والحناء والملصقات المؤقتة والزينة المغسولة بدائل جائزة تماما.', 'ورحمتان تخففان الحواف دون تغيير الخط الوضوء والغسل فوق الوشم صحيح فالصبغ تحت الجلد والماء يصل كل سطح يغسل فالاثم في الفعل لا في الغسل وصلاة الموشوم صحيحة لا تترك ابدا. فالمسلم الموشوم يصلي ويصوم كاملا من اليوم فالندم وقود توبة لا ترك عبادة.'] }, { h: 'المسلمون الجدد والازالة والثقب والتجميل', ps: ['وشم ما قبل الاسلام بجهل او ماض يمحى بالاسلام والتوبة ولا الزام بالليزر ان كان مكلفا او مؤلما او مشوها واستر حيث سهل باكمام ومساحيق ودع الماضي مدفونا. ولوشم بعد العلم ينصح العلماء بالازالة حيث امنت ورخصت والستر حيث لا وخطط للازالة مع توبة خير من ياس مع اظهار. ولا تعيد الحبر لتغطية برسوم اسلامية فالزيادة تضاعف لا تلغي.', 'والثقب ثقب الاذن والانف للمرأة للزينة جائز بالعرف واحاديث حلي العيد تفترض اذانا مثقوبة وتشبه الرجال بالنساء في الزينة محرم والثقوب الكثيرة المتطرفة تدخل في التغيير والضرر. وخطوط اوسع النمص للتجميل ملعون في نفس مجموعة الاحاديث واترك تفصيل الطبي والحاجب الملتحم للعلماء بينما الختان وتقليم الاظافر والادهان والزينة المباحة فطرة فتجمل داخل حدود الله.'] } ], steps: ['اقبل الحكم الوشم الدائم حرام والبدائل المؤقتة والحناء مفتوحة.', 'ان كنت موشوما فتب ولا تترك الصلاة واستر حيث سهل.', 'خطط لازالة امنة ميسورة ولا تغط بحبر جديد.', 'للنساء ثقب الاذن والانف للزينة جائز وللرجال تجنب التشبه.', 'الزم التجميل داخل خطوط الفطرة واسال العلماء في الدقيق.'], faq: [ { q: 'هل الوشم حرام في الاسلام', a: 'نعم فقد لعن النبي الواشمة والمستوشمة. والحناء والتصاميم المغسولة بدائل جائزة.' }, { q: 'عندي وشم هل وضوئي وصلاتي صحيحان', a: 'نعم صحيحان تماما فالصبغ تحت الجلد والماء يصل كل سطح. فتب وحافظ على كل صلاة واستر حيث سهل وازل حيث امن ورخص.' }, { q: 'هل يزيل المسلم الجديد وشمه القديم', a: 'لا الزام ان كانت الازالة مكلفة او مؤلمة او مشوهة فالاسلام يمحو الماضي. واستر حيث سهل وامض قدما والازالة تنصح حيث امنت ورخصت.' } ], aliasesAr: ['حكم الوشم في الاسلام', 'حكم الثقب والنمص'] },
  'hijab-ruling-evidence': { title: 'الحجاب في الاسلام حكمه وادلته وحدوده', intro: 'هل الحجاب واجب في الاسلام الادلة القرانية وما يجب ستره وحكم النقاب واجابات صادقة عن اصعب اسئلة الحجاب.', sections: [ { h: 'الحكم وادلته', ps: ['الحجاب واجب بنصوص قاطعة لا ثقافة وليضربن بخمرهن على جيوبهن في 24:31 امر بتغطية الشعر والعنق والصدر ويدنين عليهن من جلابيبهن في 33:59 امر بالعباءة العامة وحدد النبي حد الستر عند البلوغ لا يرى منها الا هذا وهذا واشار للوجه والكفين. واربعة عشر قرنا من العلم تقره وشعار الحجاب اختيار يخلط بين امر الله الثابت وكفاح اللابسة المحترم فالمجاهدة المتعثرة خير من التاركة الواثقة.', 'وما يجب ستره امام الاجانب كل شيء الا الوجه والكفين عند الجمهور مع راي قوي يوجب النقاب فكلاهما علم معتبر فالمنقبة وغيرها اختان تحت اية واحدة لا معسكران. وشروط الحجاب الصحيح كثيف وفضفاض يخفي الشكل ورزين لا دعاية عطر او شهرة ومخالف للباس الرجال فحجاب ضيق مع عباءة لاصقة يخفق في غايته مهما كان الغطاء.'] }, { h: 'المحارم والسن والاسئلة الصعبة', ps: ['التكشف امام المحارم الاب والاخوة والابناء والاعمام والاصهار في قائمة 24:31 ضمن الحياء وحجاب كامل امام ابناء العم واخ الزوج الذي سماه النبي الموت لشدة الحد وكل اجنبي ومنه المعلم والزميل. وتتدرب البنت من نحو سبع وتغطي عند البلوغ وللعجوز التي لا ترجو نكاحا رخصة 24:60 بتخفيف محتشم دون تبرج فلكل سن حكمها.', 'واجابات صعبة بصدق الاكراه يفسد فالقران ينفي اكراه القبول في 2:256 ويامر بالحشمة عملا فالاب والزوج ينصح ويسهل ويقتدي لا يضرب ولا يحبس. وحظر الحجاب في العمل يرخص فيه العلماء للضرورة فرديا مع البحث عن مخرج افضل فاسال ولا تفت بنفسك. والتحرش ذنب المتحرش لا خطأ الضحية وحجابها ومع ذلك يبقى الحجاب امر الله مهما كانت نظرة المجتمع. فابدئي حيث انت وزيدي طبقة هذا الاسبوع واتقنيها الشهر التالي.'] } ], steps: ['اقبل الحكم من اياته وافصل بين امر الله وكفاحك.', 'غط من الشعر الى القدمين فضفاضا كثيفا امام كل اجنبي.', 'تعلم قائمة المحارم واحفظ الحدود مع الاقارب والاصهار.', 'زد الطبقات تدريجا واسال العلماء في حالات العمل.', 'للاباء والازواج انصحوا ويسروا ولا تكرهوا ابدا.'], faq: [ { q: 'هل الحجاب واجب ام اختيار شخصي', a: 'واجب بنصوص قرانية قاطعة 24:31 و33:59 واربعة عشر قرنا من العلم. والكفاح فيه محترم وماجور وانكار وجوبه هو خط الخطر.' }, { q: 'هل تغطية الوجه واجبة النقاب', a: 'الجمهور يوجب كل شيء الا الوجه والكفين وراي قوي يضيف الوجه. وكلاهما علم معتبر فاتبع العلماء دون ذم الراي الاخر.' }, { q: 'هل يجبر الاباء البنات على الحجاب', a: 'علموا ويسروا وتوقعوا لكن الاكراه يفسد. فانصحوا بحكمة وقدوة في البيت وابدءوا التوقع من سبع ويسروا التغطية بجميل مريح.' } ], aliasesAr: ['هل الحجاب فرض وادلة القران', 'حكم النقاب وما يجب ستره'] },
  'marital-rights-conflict': { title: 'حقوق الزوجين وحل الخلاف في الاسلام', intro: 'حقوق الزوج والزوجة في الاسلام النفقة والمعاشرة والمودة وحدود الطاعة مع سلم الصلح القراني باربع درجات قبل الطلاق.', sections: [ { h: 'الحقوق المتبادلة ما لكل منهما', ps: ['الزواج ميثاق غليظ في 4:21 بحقوق متبادلة فعلى الزوج النفقة سكنا وطعما وكسوة حسب القدرة في 65:7 والمعاشرة بالمعروف في 4:19 في كل مزاج وحفظ العرض والخصوصية ومودة مقدرة فالغلظة والبخل مع القدرة وافشاء اسرار الفراش الملعون كلها خرق للميثاق. ولم يضرب النبي زوجا ولا خادما فمثاله يغلق كل ثغرة قسوة.', 'وعلى الزوجة طاعة معقولة في المعروف فالقوامة في 4:34 مسؤولية لا استبداد وحفظ البيت والعرض في الغيبة والشكر الذي يرى الرزق فتحذير اكثر اهل النار تنبيه من الجحود لا وصم قيمة. وعلى الاثنين بذل المعاشرة ضمن المودة وحفظ الولاء والمودة والرحمة في 30:21 التي تبقى بعد الرومانسية. والحقوق تنال بالعطاء اولا فمن ادى قائمته اصلح الزواج اسرع.'] }, { h: 'سلم الخلاف باربع درجات وضوابطه', ps: ['تسلسل الله للنشوز في 4:34 و35 اولا الوعظ بكلام هادئ خاص ومحدد عن الله وعواقبه لا صراخ. وثانيا الهجر في المضجع بمسافة كريمة تشعر بالجد لا حرب صمت شهورا. وثالثا الضرب الرمزي الذي وصفه العلماء غير مبرح ولا معلم وقد قال النبي ليس اولئك بخياركم وكثير من المعاصرين ينصحون بتجاوزه الى الرابعة. ورابعا التحكيم بحكم من اهله وحكم من اهلها في الاية 4:35 قبل المحاكم ومع العلماء والمستشارين.', 'وضوابط مطلقة لا ضرب وجه ولا اثر ولا اهانة ولا خنق مالي ولا استعمال الاولاد سلاحا فخرقها ظلم يحاسب عليه الله مهما كانت لغة الحقوق. وللمتضررة مخرج الخلع مع حماية الاسرة والقانون وللزوج الصبر والمشورة والتحكيم قبل اي خطوة. وغاية السلم في كل درجة الصلح فالله يوفق المحكمين الصادقين فاصعد للاصلاح لا للعقاب.'] } ], steps: ['تعلم قائمتي الحقوق وابدأ باداء حقك قبل مطالبة حقك.', 'عند الخلاف وعظ خاص اولا بكلام هادئ محدد واع بالله.', 'ثم مسافة كريمة ثم تحكيم بحكم من كل اسرة.', 'التزم الضوابط لا عنف ولا اهانة ولا ظلم مالي ابدا.', 'عند استمرار الضرر خلع ومشورة وحماية قانونية وراجع دليل الطلاق.'], faq: [ { q: 'ما واجبات الزوج نحو زوجته', a: 'النفقة حسب القدرة والمعاشرة بالمعروف دائما في 4:19 وحفظ العرض والخصوصية ومودة مقدرة ومثال النبي لا ضرب ولا اهانة ولا تحقير.' }, { q: 'هل يسمح الاسلام بضرب الزوجات', a: 'تسلسل الاية 4:34 ينتهي لفعل رمزي نهى عنه النبي نفسه وكثير من العلماء ينصح بالتحكيم بدله. وكل عنف او اثر او اهانة ظلم محرم صراحة.' }, { q: 'كيف يحل الزوجان شجارهما', a: 'سلم الله وعظ هادئ ثم مسافة كريمة ثم حكمان من الاسرتين في 4:35 مع العلماء والمستشارين وعند استمرار الضرر خلع او حماية قانونية.' } ], aliasesAr: ['حقوق الزوجين في الاسلام', 'حل الخلاف الزوجي والنشوز'] },
};
